    .prepare(
      `SELECT c.name AS customer, COUNT(*) AS orders
         FROM customers c
         JOIN orders o ON o.customer_id = c.id
        WHERE o.placed_on >= ?
        GROUP BY c.id
       HAVING COUNT(*) >= ?
        ORDER BY orders DESC, c.name`
    )
    .all(sinceDate, minOrders)
    .map((row) => ({ ...row }));
}

