export function boughtTogether(db, minTimes) {
  return db
    .prepare(
      `SELECT pa.name  AS product_a,
              pb.name  AS product_b,
              COUNT(*) AS times
         FROM order_items a
         JOIN order_items b ON b.order_id   = a.order_id
