// Provided: two queries whose plans you are about to change.
const BY_CUSTOMER = `
  SELECT c.name AS name, o.id AS id
    FROM orders o
    JOIN customers c ON c.id = o.customer_id
   WHERE o.customer_id = ?
   ORDER BY o.id
`;
const ONE_ORDERS_LINES = `
